content:
:root {
  --bg-color: #1a1a2e;
  --panel-color: #16213e;
  --accent-color: #0f3460;
  --text-color: #e94560;
  --text-main: #ffffff;
  --snake-color: #4ecc6d;
  --food-color: #ff5252;
  --board-bg: #0f172a;
  --btn-bg: #e94560;
  --btn-hover: #ff6b6b;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  user-select: none;
}

body {
  background-color: var(--bg-color);
  color: var(--text-main);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  overflow: hidden;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: 480px;
  height: 100vh;
  max-height: 850px;
  background-color: var(--panel-color);
  padding: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);
  border-radius: 12px;
  position: relative;
}

.game-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  gap: 8px;
}

.game-header h1 {
  font-size: 1.5rem;
  color: var(--text-color);
  letter-spacing: 1px;
}

.score-board {
  display: flex;
  justify-content: space-around;
  width: 100%;
  background-color: var(--accent-color);
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: bold;
}

.game-board {
  position: relative;
  width: 320px;
  height: 320px;
  background-color: var(--board-bg);
  border: 4px solid var(--accent-color);
  border-radius: 8px;
  display: grid;
  grid-template-columns: repeat(20, 1fr);
  grid-template-rows: repeat(20, 1fr);
  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.5);
}

.snake-segment {
  background-color: var(--snake-color);
  border-radius: 3px;
  border: 1px solid rgba(0, 0, 0, 0.2);
}

.food {
  background-color: var(--food-color);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--food-color);
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  0% { transform: scale(0.8); }
  100% { transform: scale(1.1); }
}

.controls-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  gap: 12px;
}

.d-pad {
  display: grid;
  grid-template-areas:
    ". up ."
    "left . right"
    ". down .";
  gap: 8px;
  width: 180px;
  height: 140px;
}

.d-btn {
  background-color: var(--accent-color);
  color: var(--text-main);
  border: none;
  border-radius: 12px;
  font-size: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
  transition: background 0.1s, transform 0.1s;
  touch-action: manipulation;
}

.d-btn:active {
  transform: scale(0.95);
  background-color: var(--text-color);
}

.d-btn:nth-child(1) { grid-area: up; }
.d-btn:nth-child(2) { grid-area: left; }
.d-btn:nth-child(3) { grid-area: right; }
.d-btn:nth-child(4) { grid-area: down; }

.btn {
  background-color: var(--btn-bg);
  color: var(--text-main);
  border: none;
  padding: 10px 24px;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
  transition: background 0.2s, transform 0.1s;
  touch-action: manipulation;
}

.btn:hover {
  background-color: var(--btn-hover);
}

.btn:active {
  transform: scale(0.95);
}

.game-over-modal {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.8);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  z-index: 10;
  border-radius: 12px;
  animation: fadeIn 0.2s ease-in-out;
}

.game-over-modal h2 {
  color: var(--text-color);
  font-size: 2rem;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
}

.game-over-modal p {
  font-size: 1.2rem;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@media (max-width: 400px) {
  .app-container {
    height: 100vh;
    max-height: none;
    border-radius: 0;
    padding: 8px;
  }
  .game-board {
    width: 280px;
    height: 280px;
  }
}

import { useState, useEffect, useCallback, useRef } from 'react';

type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';
type Position = { x: number; y: number };

const GRID_SIZE = 20;

export default function App() {
  const [snake, setSnake] = useState<Position[]>([
    { x: 10, y: 10 },
    { x: 10, y: 11 },
    { x: 10, y: 12 }
  ]);
  const [direction, setDirection] = useState<Direction>('UP');
  const [food, setFood] = useState<Position>({ x: 5, y: 5 });
  const [isGameOver, setIsGameOver] = useState<boolean>(false);
  const [score, setScore] = useState<number>(0);
  const [highScore, setHighScore] = useState<number>(() => {
    const saved = localStorage.getItem('snake_highscore');
    return saved ? parseInt(saved, 10) : 0;
  });
  const [speed, setSpeed] = useState<number>(150);

  const directionRef = useRef(direction);
  directionRef.current = direction;

  const generateFood = useCallback((currentSnake: Position[]): Position => {
    let newFood: Position;
    while (true) {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
      const collision = currentSnake.some(segment => segment.x === newFood.x && segment.y === newFood.y);
      if (!collision) break;
    }
    return newFood;
  }, []);

  const resetGame = () => {
    const initialSnake = [
      { x: 10, y: 10 },
      { x: 10, y: 11 },
      { x: 10, y: 12 }
    ];
    setSnake(initialSnake);
    setDirection('UP');
    directionRef.current = 'UP';
    setFood(generateFood(initialSnake));
    setScore(0);
    setIsGameOver(false);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)) {
        e.preventDefault();
      }
      switch (e.key) {
        case 'ArrowUp':
          if (directionRef.current !== 'DOWN') setDirection('UP');
          break;
        case 'ArrowDown':
          if (directionRef.current !== 'UP') setDirection('DOWN');
          break;
        case 'ArrowLeft':
          if (directionRef.current !== 'RIGHT') setDirection('LEFT');
          break;
        case 'ArrowRight':
          if (directionRef.current !== 'LEFT') setDirection('RIGHT');
          break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  useEffect(() => {
    if (isGameOver) return;

    const timer = setInterval(() => {
      setSnake(prevSnake => {
        const head = { ...prevSnake[0] };
        switch (directionRef.current) {
          case 'UP': head.y -= 1; break;
          case 'DOWN': head.y += 1; break;
          case 'LEFT': head.x -= 1; break;
          case 'RIGHT': head.x += 1; break;
        }

        if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
          setIsGameOver(true);
          return prevSnake;
        }

        for (let i = 0; i < prevSnake.length; i++) {
          if (prevSnake[i].x === head.x && prevSnake[i].y === head.y) {
            setIsGameOver(true);
            return prevSnake;
          }
        }

        const newSnake = [head, ...prevSnake];

        if (head.x === food.x && head.y === food.y) {
          const newScore = score + 10;
          setScore(newScore);
          if (newScore > highScore) {
            setHighScore(newScore);
            localStorage.setItem('snake_highscore', newScore.toString());
          }
          setFood(generateFood(newSnake));
        } else {
          newSnake.pop();
        }

        return newSnake;
      });
    }, speed);

    return () => clearInterval(timer);
  }, [isGameOver, food, generateFood, score, highScore, speed]);

  const changeDirection = (newDir: Direction) => {
    if (newDir === 'UP' && directionRef.current !== 'DOWN') setDirection('UP');
    if (newDir === 'DOWN' && directionRef.current !== 'UP') setDirection('DOWN');
    if (newDir === 'LEFT' && directionRef.current !== 'RIGHT') setDirection('LEFT');
    if (newDir === 'RIGHT' && directionRef.current !== 'LEFT') setDirection('RIGHT');
  };

  const toggleSpeed = () => {
    setSpeed(prev => {
      if (prev === 200) return 150;
      if (prev === 150) return 100;
      return 200;
    });
  };

  const getSpeedLabel = () => {
    if (speed === 200) return '速度: 遅い';
    if (speed === 150) return '速度: 普通';
    return '速度: 速い';
  };

  return (
    <div className="app-container">
      <div className="game-header">
        <h1>スネークゲーム</h1>
        <div className="score-board">
          <span>スコア: {score}</span>
          <span>ハイスコア: {highScore}</span>
        </div>
      </div>

      <div className="game-board">
        {snake.map((seg, idx) => (
          <div
            key={idx}
            className="snake-segment"
            style={{
              gridColumnStart: seg.x + 1,
              gridRowStart: seg.y + 1
            }}
          />
        ))}
        <div
          className="food"
          style={{
            gridColumnStart: food.x + 1,
            gridRowStart: food.y + 1
          }}
        />

        {isGameOver && (
          <div className="game-over-modal">
            <h2>ゲームオーバー</h2>
            <p>スコア: {score}</p>
            <button className="btn" onClick={resetGame}>
              リトライ
            </button>
          </div>
        )}
      </div>

      <div className="controls-container">
        <div style={{ display: 'flex', gap: '8px', marginBottom: '4px' }}>
          <button className="btn" onClick={toggleSpeed} style={{ padding: '6px 12px', fontSize: '0.85rem' }}>
            {getSpeedLabel()}
          </button>
        </div>
        <div className="d-pad">
          <button className="d-btn" onClick={() => changeDirection('UP')}>▲</button>
          <button className="d-btn" onClick={() => changeDirection('LEFT')}>◀</button>
          <button className="d-btn" onClick={() => changeDirection('RIGHT')}>▶</button>
          <button className="d-btn" onClick={() => changeDirection('DOWN')}>▼</button>
        </div>
      </div>
    </div>
  );
}
